function inlineMarkdown(v){return escapeHtml(v).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/~~([^~\n]+)~~/g,'<del>$1</del>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_\n]+)__/g,'<strong>$1</strong>').replace(/(^|[\s(])\*([^*\n]+)\*/g,'$1<em>$2</em>').replace(/(^|[\s(])_([^_\n]+)_/g,'$1<em>$2</em>')}
    function markdownResourceTokens(line){return[...String(line||'').matchAll(/\[([ xX])\]/g)].map(match=>({start:match.index||0,end:(match.index||0)+3,filled:match[1].toLowerCase()==='x'}))}
