    function renderMarkdown(v){const lines=String(v||'').split(/\r?\n/);let html='',list=false;const close=()=>{if(list){html+='</ul>';list=false}};for(const line of lines){const task=line.match(/^\s*[-*]\s+\[([ xX])\]\s*(.*)$/);if(task){close();html+=`<div class="detail-md-task"><input type="checkbox" disabled ${task[1].toLowerCase()==='x'?'checked':''}><span>${inlineMarkdown(task[2])}</span></div>`;continue}const resource=renderStaticResourceLine(line);if(resource){close();html+=resource;continue}const item=line.match(/^\s*[-*]\s+(.+)/);if(item){if(!list){html+='<ul>';list=true}html+=`<li>${inlineMarkdown(item[1])}</li>`;continue}close();const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading){const level=heading[1].length;html+=`<h${level}>${inlineMarkdown(heading[2])}</h${level}>`}else if(!line.trim()){html+='<br>'}else{html+=`<p>${inlineMarkdown(line)}</p>`}}close();return html||'<p class="muted">Не указано</p>'}
