    function updateBestiaryTagSummary(){const count=bestiaryTagFilters.size;el('bestiary-tag-summary').textContent=!count?'Все теги':count===1?state.tags.find(t=>bestiaryTagFilters.has(t.id))?.name||'1 тег':`${count} ${plural(count,'тег','тега','тегов')}`}
    function renderBestiaryTagOptions(){el('bestiary-tag-options').innerHTML=`<label class="tag-option"><input id="bestiary-all-tags" type="checkbox" ${bestiaryTagFilters.size?'':'checked'}><span>Все теги</span></label>${state.tags.map(t=>`<label class="tag-option"><input type="checkbox" data-bestiary-tag="${t.id}" ${bestiaryTagFilters.has(t.id)?'checked':''}><span class="tag-check-dot" style="--tag-color:${validTagColor(t.color)}"></span><span>${escapeHtml(t.name)}</span></label>`).join('')}`;updateBestiaryTagSummary()}
    function renderBestiary(){el('content').innerHTML=`<header class="page-head"><div><p class="eyebrow">Общая библиотека</p><h1>Бестиарий</h1></div><div class="actions"><details class="file-actions-menu"><summary class="button">⇅ JSON</summary><div class="file-actions-popover"><button class="button" id="download-creatures">↓ Скачать существ</button><button class="button" id="upload-creatures">↑ Загрузить существ</button><button class="button" id="import-lss-character" title="Создать существо из файла персонажа Long Story Short">↥ Импорт LSS</button></div></details><button class="button" id="manage-tags">⚑ Теги</button><button class="button primary" id="new-creature">＋ Создать существо</button></div></header><section class="bestiary-tools" aria-label="Поиск, фильтры и сортировка"><input class="tool-control" id="bestiary-search" type="search" value="${escapeHtml(bestiaryQuery)}" placeholder="${bestiaryAdvancedSearch?'Расширенный поиск по существам…':'Поиск по названию или описанию…'}" aria-label="${bestiaryAdvancedSearch?'Расширенный поиск существ':'Поиск существ по названию или описанию'}"><details class="tag-select bestiary-tag-select" id="bestiary-tag-select"><summary id="bestiary-tag-summary">Все теги</summary><div class="tag-option-list" id="bestiary-tag-options"></div></details><select class="tool-control" id="bestiary-sort" aria-label="Сортировка Бестиария"><option value="number" ${bestiarySort==='number'?'selected':''}>По номеру</option><option value="tag" ${bestiarySort==='tag'?'selected':''}>По тегу</option><option value="name-asc" ${bestiarySort==='name-asc'?'selected':''}>По алфавиту: А—Я</option><option value="name-desc" ${bestiarySort==='name-desc'?'selected':''}>По алфавиту: Я—А</option></select></section><section class="grid" id="bestiary-grid"></section>`;renderBestiaryTagOptions();renderBestiaryCards()}
    function renderRooms(){const cards=state.rooms.map((r,i)=>`<article class="card room-card" data-open-room="${r.id}" tabindex="0" role="button"><span class="card-kicker">Комната ${String(i+1).padStart(2,'0')}</span><h3>${escapeHtml(r.name)}</h3><p>${r.entries.length} ${plural(r.entries.length,'существо','существа','существ')}</p><div class="card-footer"><button class="mini" data-open-room="${r.id}">Открыть комнату</button></div></article>`).join('');el('content').innerHTML=`<header class="page-head"><div><p class="eyebrow">Игровые пространства</p><h1>Комнаты</h1><p class="lead">Выберите комнату или создайте новую.</p></div><div class="actions"><button class="button primary" id="new-room">＋ Создать комнату</button></div></header><section class="grid">${cards||empty('Комнат пока нет','Создайте первую комнату, а затем наполните её существами из бестиария.','Создать комнату','empty-room')}</section>`}
    function newRoomEntry(creatureId=null,npc=null){return{id:makeId(),creatureId,npc:creatureId?undefined:(npc||{name:'',description:'',hp:'',ac:'',characteristics:CHARACTERISTICS_TEMPLATE,abilities:'',notes:'',tagIds:[]})}}
    function orderedRoomCreatures(room){return room.entries.map((entry,index)=>({entry,creature:entryCreature(entry),index,initiative:room.initiatives[entry.id]})).filter(x=>x.creature).sort((a,b)=>{const av=a.initiative===''||a.initiative==null?-Infinity:Number(a.initiative),bv=b.initiative===''||b.initiative==null?-Infinity:Number(b.initiative);return bv-av||a.index-b.index})}
    function isOutsideCombat(item){return item.initiative!==''&&item.initiative!=null&&Number.isFinite(Number(item.initiative))&&Number(item.initiative)<=0}
    function combatRoomCreatures(room){return orderedRoomCreatures(room).filter(item=>!isOutsideCombat(item))}
    function ensureCombatTurn(room,ordered){if(!room.combat.active)return false;if(!ordered.length){room.combat={active:false,round:1,turnCreatureId:null};return true}if(!ordered.some(x=>x.entry.id===room.combat.turnCreatureId)){room.combat.turnCreatureId=ordered[0].entry.id;return true}return false}
    function renderRounds(round){const start=round<=2?1:round-1;return [start,start+1,start+2].map(n=>`<span class="round-step ${n===round?'current':n<round?'past':''}" ${n===round?'aria-current="step"':''}>${n}</span>`).join('')}
    function healthDanger(current,max){if(current===''||max===''||!Number.isFinite(Number(current))||!Number.isFinite(Number(max))||Number(max)<=0)return null;const ratio=Number(current)/Number(max);if(ratio>=.5)return null;const level=Math.max(0,Math.min(1,(.5-Math.max(0,ratio))/.5));return{alpha:(.14+level*.58).toFixed(3),shadow:(.08+level*.3).toFixed(3)}}
    function applyHealthState(row,current,max){if(!row)return;const danger=healthDanger(current,max);row.classList.toggle('is-wounded',Boolean(danger));if(danger){row.style.setProperty('--danger-alpha',danger.alpha);row.style.setProperty('--danger-shadow',danger.shadow)}else{row.style.removeProperty('--danger-alpha');row.style.removeProperty('--danger-shadow')}}
    function renderRoom(){const room=roomById(view.roomId);if(!room){go('rooms');return}const ordered=orderedRoomCreatures(room);if(ensureCombatTurn(room,ordered))save();const rows=ordered.map(x=>{const key=x.entry.id,current=Object.prototype.hasOwnProperty.call(room.currentHp,key)?room.currentHp[key]:x.creature.hp,isTurn=room.combat.active&&room.combat.turnCreatureId===key,danger=healthDanger(current,x.creature.hp),dangerStyle=danger?` style="--danger-alpha:${danger.alpha};--danger-shadow:${danger.shadow}"`:'';return `<article class="initiative-row ${isTurn?'is-turn ':''}${danger?'is-wounded':''}"${dangerStyle} ${isTurn?'aria-current="true"':''}><input class="initiative-input" type="number" inputmode="numeric" min="-99" max="999" value="${x.initiative??''}" placeholder="—" aria-label="Инициатива: ${escapeHtml(x.creature.name||'NPC')}" data-initiative="${key}"><button class="creature-open" data-open-detail="${key}"><span class="initiative-name">${escapeHtml(x.creature.name||'Без имени')}</span><span class="initiative-characteristics">${renderCompactMarkdown(x.creature.characteristics)}</span></button><div class="stat-pair"><div class="hp-wrap"><label class="hp-control" title="Нажмите на текущее ХП, чтобы нанести урон, вылечить или добавить бонусные хиты"><span class="stat-icon" aria-hidden="true">♡</span><input class="hp-current" type="number" inputmode="numeric" min="-999999" max="999999" value="${escapeHtml(current)}" placeholder="—" aria-label="Текущие ХП: ${escapeHtml(x.creature.name||'NPC')}" data-current-hp="${key}"><span class="hp-max">/ ${x.creature.hp===''?'—':escapeHtml(x.creature.hp)}</span></label><div class="hp-popover" data-hp-popover="${key}" hidden><div class="hp-adjust-row"><button class="hp-step" type="button" data-hp-step="-1" aria-label="Уменьшить значение на один">−</button><input class="hp-amount" type="number" inputmode="numeric" min="0" max="999999" step="1" value="0" data-hp-amount aria-label="Количество урона, лечения или бонусных хитов"><button class="hp-step" type="button" data-hp-step="1" aria-label="Увеличить значение на один">＋</button></div><div class="hp-change-actions"><button class="hp-change hp-damage" type="button" data-hp-change="damage" data-hp-entry="${key}">⚔ Урон</button><button class="hp-change hp-heal" type="button" data-hp-change="heal" data-hp-entry="${key}">♡ Лечение</button><button class="hp-change hp-bonus" type="button" data-hp-change="bonus" data-hp-entry="${key}">＋ Бонусные хиты</button></div></div></div><span class="stat-pill"><b><span class="stat-icon" aria-hidden="true" title="Класс доспеха">🛡</span><span class="sr-only">Класс доспеха</span></b><span>${x.creature.ac===''?'—':escapeHtml(x.creature.ac)}</span></span></div><div class="battle-note-shell" data-battle-note-shell="${key}"><div class="battle-note-preview ${String(room.combatNotes[key]||'').trim()?'':'is-empty'}" tabindex="0" role="button" aria-label="Боевая заметка: ${escapeHtml(x.creature.name||'NPC')}" data-combat-note-preview="${key}">${renderBattleNotePreview(room.combatNotes[key]||'',key)}</div><textarea class="battle-note" rows="2" maxlength="500" placeholder="Боевая заметка…" aria-label="Редактировать боевую заметку: ${escapeHtml(x.creature.name||'NPC')}" data-combat-note="${key}" hidden>${escapeHtml(room.combatNotes[key]||'')}</textarea></div><button class="row-action" data-remove-from-room="${key}" aria-label="Убрать ${escapeHtml(x.creature.name||'NPC')} из комнаты">✕</button></article>`}).join(''),actions=room.combat.active?'':`<button class="button" id="start-combat">▶ Начать бой</button>`,combatPanel=room.combat.active?`<section class="combat-panel" aria-label="Ход боя"><div class="round-tracker"><span class="round-label">Раунд</span>${renderRounds(room.combat.round)}</div><div class="combat-actions"><button class="button danger-button" id="end-combat">Завершить бой</button><button class="button primary" id="next-turn">Следующий ход →</button></div></section>`:'';el('content').innerHTML=`<header class="page-head"><div><p class="eyebrow">Трекер инициативы</p><div class="room-title-line"><h1>${escapeHtml(room.name)}</h1><button class="settings-button" id="settings-room" aria-label="Настройки комнаты" title="Настройки комнаты">⚙</button></div></div><div class="actions">${actions}<button class="button" id="create-npc">＋ Создать NPC</button><button class="button primary" id="add-from-bestiary">＋ Добавить из бестиария</button></div></header>${combatPanel}<section class="initiative-list">${rows||empty('В комнате никого нет','Создайте NPC или добавьте участника из общего бестиария.','Создать NPC','empty-npc')}</section>`}
    const renderRoomBase=renderRoom;
    function enhanceRoomJournal(){if(!journalEnabled)return;const actions=document.querySelector('.page-head .actions');if(actions)actions.insertAdjacentHTML('afterbegin','<button class="button journal-button" id="open-journal"><span class="journal-book" aria-hidden="true">📕</span> Журнал</button>')}
    function enhanceRoomBonusHp(){const room=roomById(view.roomId);if(!room)return;room.bonusHp=room.bonusHp&&typeof room.bonusHp==='object'?room.bonusHp:{};document.querySelectorAll('[data-hp-change="bonus"]').forEach(button=>button.hidden=!bonusHpEnabled);document.querySelectorAll('[data-current-hp]').forEach(hpInput=>{const hpWrap=hpInput.closest('.hp-wrap');if(!hpWrap)return;const hpControl=hpWrap.querySelector('.hp-control');if(hpControl)hpControl.title=bonusHpEnabled?'Нажмите на текущее ХП, чтобы нанести урон, вылечить или добавить бонусные хиты':'Нажмите на текущее ХП, чтобы нанести урон или вылечить';if(!bonusHpEnabled)return;const key=hpInput.dataset.currentHp,stored=Object.prototype.hasOwnProperty.call(room.bonusHp,key)?room.bonusHp[key]:'';hpWrap.insertAdjacentHTML('beforebegin',`<label class="bonus-hp-control" title="Бонусные хиты"><span class="bonus-hp-icon" aria-hidden="true">✦</span><input class="bonus-hp-current" type="number" inputmode="numeric" min="0" max="999999" value="${escapeHtml(stored)}" placeholder="—" aria-label="Бонусные хиты" data-bonus-hp="${key}"></label>`)})}
    renderRoom=function(){renderRoomBase();enhanceRoomJournal();enhanceRoomBonusHp()};
    function renderBattleResourceLine(line,entryId,lineIndex){const tokens=markdownResourceTokens(line);if(!tokens.length)return'';let html='',cursor=0;for(const token of tokens){if(token.start>cursor)html+=inlineMarkdown(line.slice(cursor,token.start));html+=`<button class="battle-resource-pip ${token.filled?'is-filled':''}" type="button" data-battle-resource="${entryId}" data-battle-line="${lineIndex}" data-battle-resource-start="${token.start}" aria-pressed="${token.filled}" aria-label="Переключить ячейку ресурса">${token.filled?'◆':'◇'}</button>`;cursor=token.end}if(cursor<line.length)html+=inlineMarkdown(line.slice(cursor));return`<div class="battle-resource-line">${html}</div>`}
    function renderBattleNotePreview(value,entryId){const text=String(value||'');if(!text.trim())return'<span class="battle-note-placeholder">Боевая заметка…</span>';return text.split(/\r?\n/).map((line,lineIndex)=>{const task=line.match(/^\s*[-*]\s+\[([ xX])\]\s*(.*)$/);if(task){const checked=task[1].toLowerCase()==='x';return`<label class="battle-task"><input type="checkbox" data-battle-task="${entryId}" data-battle-line="${lineIndex}" ${checked?'checked':''}><span>${inlineMarkdown(task[2])}</span></label>`}const resource=renderBattleResourceLine(line,entryId,lineIndex);if(resource)return resource;return`<div>${line?inlineMarkdown(line):'<br>'}</div>`}).join('')}
    function refreshBattleNoteShell(area){if(!area)return;const shell=area.closest('.battle-note-shell'),preview=shell?.querySelector('[data-combat-note-preview]');if(!preview)return;preview.innerHTML=renderBattleNotePreview(area.value,area.dataset.combatNote);preview.classList.toggle('is-empty',!area.value.trim())}
    function beginBattleNoteEditing(entryId,selectionEnd=true){const shell=document.querySelector(`.battle-note-shell[data-battle-note-shell="${CSS.escape(String(entryId))}"]`),area=shell?.querySelector('[data-combat-note]'),preview=shell?.querySelector('[data-combat-note-preview]');if(!area||!preview)return null;preview.hidden=true;area.hidden=false;area.focus();if(selectionEnd){const end=area.value.length;area.setSelectionRange(end,end)}return area}
    function endBattleNoteEditing(area){if(!area)return;refreshBattleNoteShell(area);const shell=area.closest('.battle-note-shell'),preview=shell?.querySelector('[data-combat-note-preview]');area.hidden=true;if(preview)preview.hidden=false}
    function renderInitiativeRow(room,x,outside=false){const key=x.entry.id,current=Object.prototype.hasOwnProperty.call(room.currentHp,key)?room.currentHp[key]:x.creature.hp,isTurn=!outside&&room.combat.active&&room.combat.turnCreatureId===key,danger=healthDanger(current,x.creature.hp),dangerStyle=danger?` style="--danger-alpha:${danger.alpha};--danger-shadow:${danger.shadow}"`:'';return `<article class="initiative-row ${isTurn?'is-turn ':''}${danger?'is-wounded':''}"${dangerStyle} ${isTurn?'aria-current="true"':''}><input class="initiative-input" type="number" inputmode="numeric" min="-99" max="999" value="${x.initiative??''}" placeholder="—" aria-label="Инициатива: ${escapeHtml(x.creature.name||'NPC')}" data-initiative="${key}"><button class="creature-open" data-open-detail="${key}"><span class="initiative-name">${escapeHtml(x.creature.name||'Без имени')}</span><span class="initiative-characteristics">${renderCompactMarkdown(x.creature.characteristics)}</span></button><div class="stat-pair"><div class="hp-wrap"><label class="hp-control" title="Нажмите на текущее ХП, чтобы нанести урон, вылечить или добавить бонусные хиты"><span class="stat-icon" aria-hidden="true">♡</span><input class="hp-current" type="number" inputmode="numeric" min="-999999" max="999999" value="${escapeHtml(current)}" placeholder="—" aria-label="Текущие ХП: ${escapeHtml(x.creature.name||'NPC')}" data-current-hp="${key}"><span class="hp-max">/ ${x.creature.hp===''?'—':escapeHtml(x.creature.hp)}</span></label><div class="hp-popover" data-hp-popover="${key}" hidden><div class="hp-adjust-row"><button class="hp-step" type="button" data-hp-step="-1" aria-label="Уменьшить значение на один">−</button><input class="hp-amount" type="number" inputmode="numeric" min="0" max="999999" step="1" value="0" data-hp-amount aria-label="Количество урона, лечения или бонусных хитов"><button class="hp-step" type="button" data-hp-step="1" aria-label="Увеличить значение на один">＋</button></div><div class="hp-change-actions"><button class="hp-change hp-damage" type="button" data-hp-change="damage" data-hp-entry="${key}">⚔ Урон</button><button class="hp-change hp-heal" type="button" data-hp-change="heal" data-hp-entry="${key}">♡ Лечение</button><button class="hp-change hp-bonus" type="button" data-hp-change="bonus" data-hp-entry="${key}">＋ Бонусные хиты</button></div></div></div><span class="stat-pill"><b><span class="stat-icon" aria-hidden="true" title="Класс доспеха">🛡</span><span class="sr-only">Класс доспеха</span></b><span>${x.creature.ac===''?'—':escapeHtml(x.creature.ac)}</span></span></div><div class="battle-note-shell" data-battle-note-shell="${key}"><div class="battle-note-preview ${String(room.combatNotes[key]||'').trim()?'':'is-empty'}" tabindex="0" role="button" aria-label="Боевая заметка: ${escapeHtml(x.creature.name||'NPC')}" data-combat-note-preview="${key}">${renderBattleNotePreview(room.combatNotes[key]||'',key)}</div><textarea class="battle-note" rows="2" maxlength="500" placeholder="Боевая заметка…" aria-label="Редактировать боевую заметку: ${escapeHtml(x.creature.name||'NPC')}" data-combat-note="${key}" hidden>${escapeHtml(room.combatNotes[key]||'')}</textarea></div><button class="row-action" data-remove-from-room="${key}" aria-label="Убрать ${escapeHtml(x.creature.name||'NPC')} из комнаты">✕</button></article>`}
    function renderRoomWithOutsideCombat(){const room=roomById(view.roomId);if(!room){go('rooms');return}const ordered=orderedRoomCreatures(room),combatants=ordered.filter(item=>!isOutsideCombat(item)),outside=ordered.filter(isOutsideCombat);if(ensureCombatTurn(room,combatants))save();const rows=combatants.map(item=>renderInitiativeRow(room,item)).join(''),outsideRows=outside.map(item=>renderInitiativeRow(room,item,true)).join(''),actions=room.combat.active?'':`<button class="button" id="start-combat">▶ Начать бой</button>`,combatPanel=room.combat.active?`<section class="combat-panel" aria-label="Ход боя"><div class="round-tracker"><span class="round-label">Раунд</span>${renderRounds(room.combat.round)}</div><div class="combat-actions"><button class="button danger-button" id="end-combat">Завершить бой</button><button class="button primary" id="next-turn">Следующий ход →</button></div></section>`:'',outsideSection=outside.length?`<section class="outside-combat" aria-label="Вне боя"><button class="outside-combat-toggle" id="toggle-outside-combat" type="button" aria-expanded="${!room.outsideCombatCollapsed}" aria-controls="outside-combat-list"><span class="outside-combat-title">Вне боя <span class="outside-combat-count">${outside.length}</span></span><span class="outside-combat-chevron" aria-hidden="true">⌃</span></button><div class="outside-combat-list" id="outside-combat-list" ${room.outsideCombatCollapsed?'hidden':''}>${outsideRows}</div></section>`:'';el('content').innerHTML=`<header class="page-head"><div><p class="eyebrow">Трекер инициативы</p><div class="room-title-line"><h1>${escapeHtml(room.name)}</h1><button class="settings-button" id="settings-room" aria-label="Настройки комнаты" title="Настройки комнаты">⚙</button></div></div><div class="actions">${actions}<button class="button" id="create-npc">＋ Создать NPC</button><button class="button primary" id="add-from-bestiary">＋ Добавить из бестиария</button></div></header>${combatPanel}<section class="initiative-list">${rows||(!outside.length?empty('В комнате никого нет','Создайте NPC или добавьте участника из общего бестиария.','Создать NPC','empty-npc'):'')}</section>${outsideSection}`;enhanceRoomJournal();enhanceRoomBonusHp()}
    renderRoom=renderRoomWithOutsideCombat;
    function startCombat(){const room=roomById(view.roomId),ordered=room&&combatRoomCreatures(room);if(!room||!ordered.length){showToast('Нет персонажей с инициативой выше 0');return}room.combat={active:true,round:1,turnCreatureId:ordered[0].entry.id};save('Бой начался');render()}
    function nextCombatTurn(){const room=roomById(view.roomId);if(!room?.combat.active)return;const ordered=combatRoomCreatures(room);if(!ordered.length){endCombat();return}let index=ordered.findIndex(x=>x.entry.id===room.combat.turnCreatureId);if(index<0)index=0;if(index>=ordered.length-1){room.combat.round++;room.combat.turnCreatureId=ordered[0].entry.id}else room.combat.turnCreatureId=ordered[index+1].entry.id;save();render();if(combatTrackingEnabled)requestAnimationFrame(()=>document.querySelector('.initiative-row.is-turn')?.scrollIntoView({behavior:'smooth',block:'center'}))}
    function endCombat(){const room=roomById(view.roomId);if(!room)return;room.combat={active:false,round:1,turnCreatureId:null};save('Бой завершён');render()}
    function openRoomDialog(id=null){editingRoomId=id;const room=roomById(id);el('room-dialog-title').textContent=room?'Настройки комнаты':'Новая комната';el('room-name').value=room?.name||'';el('delete-room').hidden=!room;el('room-dialog').showModal();setTimeout(()=>el('room-name').focus(),0)}
