    async function importLssCharacterFile(file){if(!file)return;if(file.size>5*1024*1024){showToast('Файл слишком большой');return}try{const raw=JSON.parse(await file.text()),doc=unwrapLssCharacter(raw);if(!doc)throw Error('format');const creature=lssCreatureFromDocument(doc);openCreatureDialog();el('creature-dialog-kicker').textContent='Импорт Long Story Short';el('creature-dialog-title').textContent='Проверить персонажа';el('creature-name').value=creature.name;el('creature-description').value=creature.description;el('creature-hp').value=creature.hp;el('creature-ac').value=creature.ac;el('creature-characteristics').value=creature.characteristics;el('creature-abilities').value=creature.abilities;el('creature-notes').value=creature.notes;showToast('Персонаж LSS распознан — проверьте данные')}catch(_){showToast('Не удалось распознать персонажа Long Story Short')}}
    let detailMarkdownTarget=null,detailMarkdownOpenId=null;
    function renderDetailResourceLine(line,lineIndex,field){const tokens=markdownResourceTokens(line);if(!tokens.length)return'';let html='',cursor=0;for(const token of tokens){if(token.start>cursor)html+=inlineMarkdown(line.slice(cursor,token.start));html+=`<button class="detail-md-resource-pip ${token.filled?'is-filled':''}" type="button" data-detail-resource-field="${field}" data-detail-line="${lineIndex}" data-detail-resource-start="${token.start}" aria-pressed="${token.filled}" aria-label="Переключить ячейку ресурса">${token.filled?'◆':'◇'}</button>`;cursor=token.end}if(cursor<line.length)html+=inlineMarkdown(line.slice(cursor));return`<p class="detail-md-resource-line">${html}</p>`}
    function renderDetailMarkdown(v,items,field,navigable=true){const lines=String(v||'').split(/\r?\n/);let html='',list=false,lastLevel=1;const addItem=(label,level,kind)=>{const id=`detail-anchor-${items.length}`;items.push({id,label,level,kind});return id},close=()=>{if(list){html+='</ul>';list=false}},withBold=text=>{const labels=navigable&&boldAsSection?[...String(text).matchAll(/\*\*([^*\n]+)\*\*|__([^_\n]+)__/g)].map(match=>markdownPreview(match[1]||match[2]).trim()).filter(Boolean):[];let index=0,rendered=inlineMarkdown(text);if(labels.length)rendered=rendered.replace(/<strong>([\s\S]*?)<\/strong>/g,(match,content)=>{const label=labels[index++];if(!label)return match;const id=addItem(label,Math.min(6,lastLevel+1),'bold');return `<strong class="detail-anchor" id="${id}">${content}</strong>`});return rendered};lines.forEach((line,lineIndex)=>{const task=line.match(/^\s*[-*]\s+\[([ xX])\]\s*(.*)$/);if(task){close();const checked=task[1].toLowerCase()==='x';html+=`<label class="detail-md-task"><input type="checkbox" data-detail-task-field="${field}" data-detail-line="${lineIndex}" ${checked?'checked':''}><span>${withBold(task[2])}</span></label>`;return}const resource=renderDetailResourceLine(line,lineIndex,field);if(resource){close();html+=resource;return}const item=line.match(/^\s*[-*]\s+(.+)/);if(item){if(!list){html+='<ul>';list=true}html+=`<li>${withBold(item[1])}</li>`;return}close();const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading){lastLevel=heading[1].length;const label=markdownPreview(heading[2]).trim(),id=navigable?addItem(label,lastLevel,'heading'):'';html+=`<h${lastLevel}${id?` class="detail-anchor" id="${id}"`:''}>${inlineMarkdown(heading[2])}</h${lastLevel}>`}else if(!line.trim()){html+='<br>'}else html+=`<p>${withBold(line)}</p>`});close();return html||'<p class="muted">Не указано</p>'}
    function renderDetailToc(items){if(!items.length)return '<p class="detail-toc-empty">Добавьте заголовки через <b>#</b>, <b>##</b> и далее — они появятся здесь.</p>';return `<div class="detail-toc-list">${items.map((item,index)=>`<button class="detail-toc-link ${index===0?'active':''}" type="button" data-detail-jump="${item.id}" style="--toc-depth:${Math.max(0,item.level-1)}" title="${escapeHtml(item.label)}"><span class="detail-toc-mark">${item.kind==='bold'?'B':`H${item.level}`}</span><span class="detail-toc-text">${escapeHtml(item.label)}</span></button>`).join('')}</div>`}
    function openCreatureDetail(id){const fromBestiary=view.name==='bestiary',room=fromBestiary?null:roomById(view.roomId),entry=fromBestiary?null:roomEntryById(room,id),c=fromBestiary?creatureById(id):entryCreature(entry);if(!c||(!fromBestiary&&!entry))return;detailMarkdownTarget=c;detailMarkdownOpenId=id;const items=[],section=(title,field,navigable=true)=>`<section class="detail-section"><h4>${title}</h4><div class="markdown">${renderDetailMarkdown(c[field],items,field,navigable)}</div></section>`,sections=section('Характеристики','characteristics',false)+section('Способности','abilities')+section('Заметки','notes'),book=!fromBestiary&&!entry.creatureId?`<button class="detail-icon" data-add-npc-to-bestiary="${entry.id}" aria-label="Добавить в Бестиарий" title="Добавить в Бестиарий">📖</button>`:'',editTitle=fromBestiary||entry.creatureId?'Изменить в Бестиарии':'Изменить NPC',editAction=fromBestiary?`data-edit-creature="${c.id}"`:`data-edit-room-entry="${entry.id}"`;el('detail-content').innerHTML=`<div class="detail-main"><div class="detail-top"><div><p class="eyebrow">Карточка существа</p><h3>${escapeHtml(c.name||'Без имени')}</h3>${c.description?`<p class="detail-description">${escapeHtml(c.description)}</p>`:''}</div><div class="detail-actions">${book}<button class="detail-icon" ${editAction} aria-label="${editTitle}" title="${editTitle}">⚙</button><button class="detail-close" data-close="detail-dialog" aria-label="Закрыть">✕</button></div></div><div class="detail-stats"><div class="detail-stat"><b>♥ ХП</b><span>${c.hp===''?'—':escapeHtml(c.hp)}</span></div><div class="detail-stat"><b>🛡 КД</b><span>${c.ac===''?'—':escapeHtml(c.ac)}</span></div></div>${sections}</div><aside class="detail-toc" aria-label="Навигация по карточке"><p class="detail-toc-title">Разделы карточки</p>${renderDetailToc(items)}</aside>`;if(!el('detail-dialog').open)el('detail-dialog').showModal()}
    function updateDetailMarkdownControl(field,lineIndex,start=null,checked=null){if(!detailMarkdownTarget||!['characteristics','abilities','notes'].includes(field))return;const lines=String(detailMarkdownTarget[field]||'').split(/\r?\n/),line=String(lines[lineIndex]||'');if(start==null){const match=line.match(/^(\s*[-*]\s+)\[([ xX])\](\s*)(.*)$/);if(!match)return;lines[lineIndex]=match[1]+(checked?'[x]':'[ ]')+match[3]+match[4]}else{const token=line.slice(start,start+3);if(!/^\[[ xX]\]$/.test(token))return;lines[lineIndex]=line.slice(0,start)+(/^\[[xX]\]$/.test(token)?'[ ]':'[x]')+line.slice(start+3)}detailMarkdownTarget[field]=lines.join('\n');save();openCreatureDetail(detailMarkdownOpenId)}
