    function renderMembershipTagOptions(){el('membership-tag-options').innerHTML=`<label class="tag-option"><input id="membership-all-tags" type="checkbox" ${membershipTagFilters.size?'':'checked'}><span>Все теги</span></label>${state.tags.map(t=>`<label class="tag-option"><input type="checkbox" data-membership-tag="${t.id}" ${membershipTagFilters.has(t.id)?'checked':''}><span class="tag-check-dot" style="--tag-color:${validTagColor(t.color)}"></span><span>${escapeHtml(t.name)}</span></label>`).join('')}`;updateMembershipTagSummary()}
    function renderRoomMembershipOptions(){const room=roomById(view.roomId),list=state.bestiary.filter(c=>creatureMatchesQuery(c,membershipQuery)&&[...membershipTagFilters].every(id=>(c.tagIds||[]).includes(id)));el('membership-checks').innerHTML=list.length?list.map(c=>{const present=room?.entries.filter(entry=>entry.creatureId===c.id).length||0,pending=membershipPendingAdds.get(c.id)||0,count=[present?`В комнате: ${present}`:'',pending?`Добавится: ${pending}`:''].filter(Boolean).join(' · ');return `<div class="check add-copy-row"><div class="add-copy-info"><span class="add-copy-name">${escapeHtml(c.name)}</span>${count?`<span class="copy-count">${count}</span>`:''}</div><button class="add-copy-button" type="button" data-add-copy="${c.id}" aria-label="Добавить ещё одну копию ${escapeHtml(c.name)}" title="Добавить копию">＋</button></div>`}).join(''):`<div class="tag-editor-empty">${state.bestiary.length?'Ничего не найдено.':'Бестиарий пока пуст.'}</div>`}
