    el('room-form').addEventListener('submit',e=>{e.preventDefault();const name=el('room-name').value.trim();if(!name)return;if(editingRoomId){roomById(editingRoomId).name=name;save('Комната изменена')}else{state.rooms.push({id:makeId(),name,journal:'',entries:[],initiatives:{},combatNotes:{},currentHp:{},bonusHp:{},combat:{active:false,round:1,turnCreatureId:null}});save('Комната создана')}el('room-dialog').close();render()})
